INSERT INTO feature VALUES('cut-schedules','machine','Concurrent schedules of a cut','sequent-machine','partial','notable',NULL,'Two cuts run by hand as two runs on two threads, each holding its own heap, answer as the sequential schedule does. A writer runs closed over a store''s values, apart from its reader''s heap: a thunk a run answered with has its captures laid out on another run''s heap, a capture two fields share counted twice, and answers on another thread as forcing it in place does. A cut''s writer runs on the driver''s pool as the left half of one join, and its reader reads the writer''s answer through a host''s reply: the two halves of a tree sum at depth 18 finish 2.02 times faster on the executor and 1.91 times natively, against 1.98 and 1.92 times for the two runs by hand, on a 16-core Ryzen 9 9950X3D at load 25 on 32 hardware threads. The rule that spawns a writer at each independent cut with an await before the binder''s first read (#2954) is owed.','surface-dispatcher surface-evaluate runtime-emitter','corpus/ledger/features/cut-schedules.gandr crates/surface-evaluate/src/evaluate.rs crates/runtime-emitter/src/run.rs crates/runtime-emitter/tests/cut.rs','corpus/ledger/features/cut-schedules.gandr','#2954');
